'use strict';

const fs = require('fs');

function realpathSync(target) {
  if (typeof target !== 'string') {
    throw new TypeError('Expected a string path');
  }

  if (typeof fs.realpathSync.native === 'function') {
    try {
      return fs.realpathSync.native(target);
    } catch (err) {
      if (err.code !== 'ERR_FEATURE_UNAVAILABLE_ON_PLATFORM') {
        throw err;
      }
    }
  }

  return fs.realpathSync(target);
}

function realpath(target, callback) {
  if (typeof target !== 'string') {
    throw new TypeError('Expected a string path');
  }
  if (typeof callback !== 'function') {
    throw new TypeError('Expected a callback function');
  }

  const native = fs.realpath.native;
  if (typeof native === 'function') {
    native(target, function (err, resolved) {
      if (err && err.code === 'ERR_FEATURE_UNAVAILABLE_ON_PLATFORM') {
        fs.realpath(target, callback);
        return;
      }
      callback(err, resolved);
    });
    return;
  }

  fs.realpath(target, callback);
}

module.exports = realpath;
module.exports.sync = realpathSync;
module.exports.realpath = realpath;
module.exports.realpathSync = realpathSync;
module.exports.default = realpath;

#!/usr/bin/env node
'use strict';

const realpath = require('../index.js');

const USAGE = 'Usage: realpath-resolver <path>';

function main(argv) {
  const target = argv[2];

  if (!target || target === '-h' || target === '--help') {
    process.stderr.write(USAGE + '\n');
    process.exit(target ? 0 : 2);
  }

  return realpath.sync(target);
}

try {
  process.stdout.write(main(process.argv) + '\n');
} catch (err) {
  process.stderr.write('realpath-resolver: ' + err.message + '\n');
  process.exit(1);
}

'use strict';

const assert = require('assert');
const fs = require('fs');
const os = require('os');
const path = require('path');

const realpath = require('../index.js');

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'realpath-resolver-'));
const targetDir = path.join(tmp, 'target');
const linkPath = path.join(tmp, 'link');
const nestedLink = path.join(tmp, 'nested', 'link');

fs.mkdirSync(targetDir);
fs.mkdirSync(path.join(tmp, 'nested'));
fs.writeFileSync(path.join(targetDir, 'file.txt'), 'hello');

const linkType = process.platform === 'win32' ? 'junction' : 'dir';
fs.symlinkSync(targetDir, linkPath, linkType);
fs.symlinkSync(linkPath, nestedLink, linkType);

const expected = realpath.sync(targetDir);

assert.strictEqual(realpath.sync(linkPath), expected);
assert.strictEqual(realpath.sync(nestedLink), expected);
assert.strictEqual(realpath.sync(path.join(linkPath, 'file.txt')), path.join(expected, 'file.txt'));

assert.throws(() => realpath.sync(123), TypeError);

const viaCallback = realpath.sync(nestedLink);
assert.strictEqual(realpath.sync(nestedLink), viaCallback);

realpath(nestedLink, function (err, resolved) {
  assert.ifError(err);
  assert.strictEqual(resolved, expected);

  fs.rmSync(tmp, { recursive: true, force: true });
  process.stdout.write('ok\n');
});
